ESCAPE_RE = r"\\(\'|\"|\\|[abfnrtv]|x.{0,2}|[0-7]{1,3})"


def _match(literal: Text) -> Match[Text]:
    """Build a Match object the same way evalString's re.sub does."""
    m = re.fullmatch(ESCAPE_RE, literal)
    assert m is not None, "test bug: %r does not match the escape regex" % literal
    return m


class TestEscape(unittest.TestCase):
    def test_simple_escapes(self):
