import unittest


ESCAPE_RE = r"\\(\'|\"|\\|[abfnrtv]|x.{0,2}|[0-7]{1,3})"


def _match(literal: Text) -> Match[Text]:
    """Build a Match object the same way evalString's re.sub does."""
    m = re.fullmatch(ESCAPE_RE, literal)
    assert m is not None, "test bug: %r does not match the escape regex" % literal
    return m


class TestEscape(unittest.TestCase):
    def test_simple_escapes(self):
        for tail, expected in simple_escapes.items():
            self.assertEqual(escape(_match("\\" + tail)), expected)

    def test_hex_escapes(self):
        cases = {
            "\\x41": "A",
            "\\x61": "a",
            "\\x7A": "z",      # uppercase hex digit accepted
            "\\x00": "\x00",
            "\\xff": "\xff",
        }
        for literal, expected in cases.items():
            self.assertEqual(escape(_match(literal)), expected)

    def test_octal_escapes(self):
        cases = {
            "\\0": "\x00",
            "\\101": "A",
            "\\7": "\x07",
            "\\777": chr(0o777),  # note: chr() accepts > 255 here, unlike Python literals
        }
        for literal, expected in cases.items():
            self.assertEqual(escape(_match(literal)), expected)

