        # The regex only matches [0-7], so an invalid octal can only be
        # produced by calling escape directly with a crafted Match.
        class FakeMatch:
            def group(self, *args):
                return "\\8", "8"
        with self.assertRaises(ValueError):
            escape(FakeMatch())  # type: ignore[arg-type]


