    def test_roundtrip_ascii(self):
        for i in range(256):
            c = chr(i)
            self.assertEqual(evalString(repr(c)), c)

    def test_triple_quoted(self):
        self.assertEqual(evalString('"""a\\nb"""'), "a\nb")
        self.assertEqual(evalString("'''a\\tb'''"), "a\tb")

    def test_unmatched_backslash_passes_through(self):
        # \8 matches no alternative in the regex, so re.sub leaves it as-is
        self.assertEqual(evalString(r"'\8'"), "\\8")

