        cases = {
            "\\x41": "A",
            "\\x61": "a",
            "\\x7A": "z",      # uppercase hex digit accepted
            "\\x00": "\x00",
            "\\xff": "\xff",
        }
        for literal, expected in cases.items():
            self.assertEqual(escape(_match(literal)), expected)

    def test_octal_escapes(self):
        cases = {
            "\\0": "\x00",
            "\\101": "A",
            "\\7": "\x07",
            "\\777": chr(0o777),  # note: chr() accepts > 255 here, unlike Python literals
